public sealed class RabbitConsumer(IModel channel)
{
    public async Task HandleAsync(
        BasicDeliverEventArgs delivery, CancellationToken cancellationToken)
    {
        try
        {
            await ProcessPayloadAsync(delivery.Body, cancellationToken);
            channel.BasicAck(delivery.DeliveryTag, multiple: false);
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            channel.BasicNack(delivery.DeliveryTag, multiple: false, requeue: true);
        }
        catch (Exception)
        {
            channel.BasicNack(delivery.DeliveryTag, multiple: false, requeue: false);
            throw; // host can observe via awaited Task
        }
    }
}

async Task FailingAsync() => throw new InvalidOperationException("boom");

// await — rethrows InvalidOperationException directly
try { await FailingAsync(); }
catch (InvalidOperationException ex) { /* caught */ }

// Wait — wraps in AggregateException
try { FailingAsync().Wait(); }
catch (AggregateException agg) { var inner = agg.InnerException; }

var tasks = new[] { FailingA(), FailingB(), FailingC() };

try
{
    await Task.WhenAll(tasks);
}
catch (Exception ex)
{
    // await WhenAll throws the FIRST fault only
    Console.WriteLine(ex.Message);
}

// To see ALL faults, inspect each task:
foreach (var t in tasks.Where(t => t.IsFaulted))
    Console.WriteLine(t.Exception!.InnerException!.Message);

// BAD — exception is unobserved until GC finalizes the Task
_ = ProcessMessageAsync(message); // no await, no ContinueWith

// BAD — ContinueWith without OnlyOnFaulted check
ProcessMessageAsync(message)
    .ContinueWith(t => Log.Error(t.Exception)); // runs on ANY completion

// GOOD — host awaits and handles
await ProcessMessageAsync(message);

// GOOD — explicit fault handler
_ = ProcessMessageAsync(message).ContinueWith(t =>
{
    if (t.IsFaulted) Log.Error(t.Exception);
}, TaskContinuationOptions.OnlyOnFaulted);
